    return max(distinct)

def is_valid_rgba_tuple(t):
    if not isinstance(t, tuple) or len(t) != 4:
        return False
    r, g, b, a = t
    channels_ok = all(
        isinstance(c, int) and not isinstance(c, bool) and 0 <= c <= 255
        for c in (r, g, b)
    )
    alpha_ok = isinstance(a, (int, float)) and not isinstance(a, bool) and 0.0 <= a <= 1.0
    return channels_ok and alpha_ok

def monogram(first, middle, last):
    order = [first, last, middle]
    initials = [name[0] for name in order]
    letters = [ch.upper() for ch in initials]
    return ''.join(letters)

