def next_prime(n):
    def is_prime(x):
        if x < 2:
            return False
        for i in range(2, int(x ** 0.5) + 1):
            if x % i == 0:
                return False
        return True
    candidate = n
    while True:
        candidate += 1
        if is_prime(candidate):
            return candidate

